package leetcode

import (
	"reflect"
	"testing"
)

func TestLengthOfLongestSubstring(t *testing.T) {
	qs := []struct {
		name string
		in   string
		want int
	}{
		{"Example 1", "abcabcbb", 3},
		{"Example 2", "bbbbb", 1},
		{"Example 3", "pwwkew", 3},
		{"长字符串超时超时", "", 30},
	}

	impls := map[string]func(string) int{
		"lengthOfLongestSubstring":        lengthOfLongestSubstring,
		"lengthOfLongestSubstringMap":     lengthOfLongestSubstringMap,
		"lengthOfLongestSubstringTimeout": lengthOfLongestSubstringTimeout,
	}

	for _, q := range qs {
		for implName, impl := range impls {
			t.Run(q.name+"/"+implName, func(t *testing.T) {
				got := impl(q.in)

				if !reflect.DeepEqual(got, q.want) {
					t.Fatalf("%v(%v) = %v, want %v", implName, q.in, got, q.want)
				}
			})
		}
	}
}
